sys_script_client.script:
function onLoad() {
    var tradeTaskType = "Checker";
    var outcome = "No corresponding Switch trade identified - put 'Trade on Hold'";
    if (tradeTaskType == 'Checker' && outcome == "No corresponding Switch trade identified - put 'Trade on Hold'") {
        g_form.setMandatory('reason_code', true);
        g_form.setMandatory('reason_description', true);
        g_form.setReadOnly('reason_code', true);
        g_form.setReadOnly('reason_description', true);
		g_form.addInfoMessage(tradeTaskType + outcome);
    }
}
